theory('Learn All Patterns of Subsequences (Theory)', 'At index i, a positional subsequence either includes a[i] or skips it. Recurse on i+1 in both cases; the measure n-i decreases. A mutable path needs push -> recurse -> pop restoration. At i==n: print/copy the path for enumeration, return whether its sum matches for existence, or return 1/0 for counting. Existence can short-circuit with OR; counting adds both branches. Duplicated values still give distinct positional choices. Pruning sum>target is only safe when all remaining values are nonnegative. Worst case is 2^n leaves and O(n) stack, with additional output cost when copying paths.')
add('Pow(x,n)', '''    public static double solve(double x,int exponent){ long n=exponent; if(n<0){ x=1/x; n=-n; } double ans=1; while(n>0){ if((n&1)==1) ans*=x; x*=x; n>>=1; } return ans; }''','System.out.println(solve(2,-3));','0.125',
    'Compute x raised to an int exponent using IEEE-754 double arithmetic; 0^0 returns 1.', 'Binary exponentiation keeps ans*x^remaining equal to the desired result. Consume low bits; square the base as the exponent halves.', 'O(log(|n|+1)) time; O(1) space.', '2^-3 becomes 0.5^3: take 0.5, square to 0.25, then take it -> 0.125.', 'Cast exponent to long before negating MIN_VALUE. Double overflow/underflow follows IEEE-754; this is not exact rational arithmetic.')
add('Generate Parentheses', '''    private static void dfs(int n,int open,int close,StringBuilder path,List<String> out){ if(close==n){ out.add(path.toString()); return; } if(open<n){ path.append('('); dfs(n,open+1,close,path,out); path.deleteCharAt(path.length()-1); } if(close<open){ path.append(')'); dfs(n,open,close+1,path,out); path.deleteCharAt(path.length()-1); } }
    public static List<String> solve(int n){ if(n<0) throw new IllegalArgumentException(); List<String> out=new ArrayList<>(); dfs(n,0,0,new StringBuilder(),out); return out; }''','System.out.println(solve(3));','[((())), (()()), (())(), ()(()), ()()()]',
    'Generate all balanced strings with n opening and n closing parentheses; n=0 yields one empty string.', 'Only add an opening when open<n, and a closing when close<open. These conditions ensure no invalid prefix is generated; every balanced string follows one such path.', 'O(n*C_n) time/output space where C_n is the nth Catalan number; O(n) recursion/path space.', 'At n=2 paths are (()) and ()(); trying to close at the initial state is forbidden.', 'Restore the builder after each branch. The returned list is exponential; large n cannot be enumerated practically.')
subsets = '''    private static void dfs(int[] a,int i,List<Integer> path,List<List<Integer>> out){ if(i==a.length){ out.add(new ArrayList<>(path)); return; } dfs(a,i+1,path,out); path.add(a[i]); dfs(a,i+1,path,out); path.remove(path.size()-1); }
    public static List<List<Integer>> solve(int[] a){ List<List<Integer>> out=new ArrayList<>(); dfs(a,0,new ArrayList<>(),out); return out; }'''
for title in ['Power Set','Subsets I']:
    add(title,subsets,'System.out.println(solve(new int[]{1,2}));','[[], [2], [1], [1, 2]]',
        'Enumerate positional subsets; skip branch is visited before take branch. Duplicate values may give equal value lists.', 'At each index choose skip or take. Copy the path at a leaf to prevent later mutations from changing stored results.', 'O(n*2^n) time/output space; O(n) stack and working path.', 'Skip 1/skip 2 -> []; skip 1/take 2 -> [2]; take 1/skip 2 -> [1]; take both -> [1,2].', 'Use remove(size-1), not remove(value), when restoring a path. Enumeration includes the empty subset.', 'Bitmask enumeration gives the same asymptotic costs with a different order.')
modpow = '''    private static long power(long x,long n){ long ans=1,mod=1000000007L; while(n>0){ if((n&1)==1) ans=ans*x%mod; x=x*x%mod; n>>=1; } return ans; }
    public static long solve(long n){ if(n<0) throw new IllegalArgumentException(); return power(5,n/2+n%2)*power(4,n/2)%1000000007L; }'''
add('Count Good Numbers',modpow,'System.out.println(solve(4));','400',
    'Length-n digit strings have an even digit at every zero-based even position and a prime digit at every odd position. Leading zeros allowed; return modulo 1e9+7.', 'Even positions have five choices {0,2,4,6,8}; odd positions four {2,3,5,7}. Independent choices multiply, so use 5^ceil(n/2)*4^floor(n/2) with modular exponentiation.', 'O(log(n+1)) time; O(1) space.', 'n=4 has two positions of each kind: 5²*4²=400.', 'Use n/2+n%2 rather than (n+1)/2 to avoid long overflow. n=0 represents one empty string.')
add('Reverse a Stack', '''    private static void bottom(Deque<Integer> stack,int x){ if(stack.isEmpty()){ stack.push(x); return; } int y=stack.pop(); bottom(stack,x); stack.push(y); }
    public static void solve(Deque<Integer> stack){ if(stack.isEmpty()) return; int x=stack.pop(); solve(stack); bottom(stack,x); }''','Deque<Integer> s=new ArrayDeque<>(Arrays.asList(1,2,3)); solve(s); System.out.println(s);','[3, 2, 1]',
    'Reverse a stack in place, using the front of ArrayDeque as its top.', 'Remove the top recursively; after reversing the remaining stack, insert the saved top at the bottom via a second recursion.', 'O(n²) time; O(n) peak recursion space.', 'Pop 1,2,3; insert 3 at bottom of empty, then 2 below 3, then 1 below them.', 'Deque iteration prints top-to-bottom here. Deep recursion can overflow the Java stack.', 'A second stack reverses in O(n) time with O(n) auxiliary storage.')
for title,count in [('Check if there exists a subsequence with sum K',False),('Count all subsequences with sum K',True)]:
    code = '''    private static %s dfs(int[] a,int i,long remaining){ if(i==a.length) return %s; return %s; }
    public static %s solve(int[] a,long k){ return dfs(a,0,k); }''' % ('BigInteger' if count else 'boolean', 'remaining==0?BigInteger.ONE:BigInteger.ZERO' if count else 'remaining==0', 'dfs(a,i+1,remaining).add(dfs(a,i+1,remaining-a[i]))' if count else 'dfs(a,i+1,remaining)||dfs(a,i+1,remaining-a[i])', 'BigInteger' if count else 'boolean')
    add(title,code,'System.out.println(solve(new int[]{1,2,1},2));','2' if count else 'true',
        'Count positional subsequences summing to k, including the empty one for k=0.' if count else 'Decide if some positional subsequence sums to k; empty subsequence is allowed.',
        'Take/skip every index. The leaf tests the remaining target. %s' % ('Counts add because the branches partition positional subsets.' if count else 'OR combines the branches and short-circuits on a witness.'),
        'O(2^n) recursive nodes; O(n) stack. BigInteger counting cost additionally depends on count bits.',
        '[1,2,1] reaches sum 2 either by taking index 1 alone or both indices 0,2.', 'Negatives and zeros are supported, so sum-based positive-only pruning is intentionally absent.',
        'Memoize (index,remaining) to avoid repeated states. Nonnegative bounded sums admit subset-sum DP; existence can use a boolean table, counting an integer table.')
add('Generate Binary Strings Without Consecutive 1s', '''    private static void dfs(int n,StringBuilder p,List<String> out){ if(p.length()==n){ out.add(p.toString()); return; } boolean canOne=p.length()==0||p.charAt(p.length()-1)=='0'; p.append('0'); dfs(n,p,out); p.deleteCharAt(p.length()-1); if(canOne){ p.append('1'); dfs(n,p,out); p.deleteCharAt(p.length()-1); } }
    public static List<String> solve(int n){ if(n<0) throw new IllegalArgumentException(); List<String> out=new ArrayList<>(); dfs(n,new StringBuilder(),out); return out; }''','System.out.println(solve(3));','[000, 001, 010, 100, 101]',
    'Generate length-n binary strings in lexicographic order, forbidding adjacent ones.', 'Zero is always allowed; one is allowed only after zero or at the first position. This excludes invalid prefixes immediately while preserving all valid choices.', 'O(n*F_(n+2)) time/output space; O(n) stack.', 'After prefix 01 only zero is allowed, producing 010.', 'n=0 gives the single empty string. Save the allowed-one condition before appending/removing zero.')
combo = '''    private static void dfs(int[] a,int start,int remaining,List<Integer> p,List<List<Integer>> out,boolean reuse){ if(remaining==0){ out.add(new ArrayList<>(p)); return; } for(int i=start;i<a.length && a[i]<=remaining;i++){ if(i>start&&a[i]==a[i-1]) continue; p.add(a[i]); dfs(a,reuse?i:i+1,remaining-a[i],p,out,reuse); p.remove(p.size()-1); } }
    public static List<List<Integer>> solve(int[] input,int target){ if(target<0) throw new IllegalArgumentException(); int[] a=input.clone(); for(int x:a) if(x<=0) throw new IllegalArgumentException("positive candidates required"); Arrays.sort(a); List<List<Integer>> out=new ArrayList<>(); dfs(a,0,target,new ArrayList<>(),out,REUSE); return out; }'''
for title,reuse in [('Combination Sum',True),('Combination Sum II',False)]:
    add(title,combo.replace('REUSE',str(reuse).lower()),'System.out.println(solve(new int[]{2,3,6,7},7));','[[2, 2, 3], [7]]' if reuse else '[[7]]',
        'Find unique nondecreasing combinations summing to target, with positive candidates. %s' % ('Each candidate may be reused.' if reuse else 'Each input position may be used once.'),
        'Sort candidates, skip duplicate siblings, and append values only at/after start. %s This makes combinations canonical and avoids permutation duplicates.' % ('Recurse at i for reuse.' if reuse else 'Recurse at i+1 to prevent reuse.'),
        'Exponential output-sensitive time; O(target/minCandidate) recursion depth for reuse, O(n) without reuse, plus sorted copy/output.',
        'For target 7, reusing 2 gives 2+2+3; candidate 7 gives a singleton. Without reuse only [7] is possible.',
        'Zero candidates would create infinite reuse recursion; reject nonpositive values. A remaining target of zero yields one completed combination.')
add('Subsets II', '''    private static void dfs(int[] a,int start,List<Integer> p,List<List<Integer>> out){ out.add(new ArrayList<>(p)); for(int i=start;i<a.length;i++){ if(i>start&&a[i]==a[i-1]) continue; p.add(a[i]); dfs(a,i+1,p,out); p.remove(p.size()-1); } }
    public static List<List<Integer>> solve(int[] input){ int[] a=input.clone(); Arrays.sort(a); List<List<Integer>> out=new ArrayList<>(); dfs(a,0,new ArrayList<>(),out); return out; }''','System.out.println(solve(new int[]{1,2,2}));','[[], [1], [1, 2], [1, 2, 2], [2], [2, 2]]',
    'Enumerate distinct value subsets when input can contain duplicates.', 'Sort so duplicates are adjacent. Skip equal values at the SAME decision depth, but allow a second equal value in a deeper decision so [2,2] remains possible.', 'O(n*2^n) worst output/time plus sort; O(n) stack and copy before output.', '[1,2,2]: skip the second 2 as a root sibling, but permit it after taking the first 2.', 'Globally forbidding duplicates would incorrectly remove subsets that use repeated input positions.')
add('Combination Sum III', '''    private static void dfs(int start,int k,int sum,List<Integer> p,List<List<Integer>> out){ if(k==0){ if(sum==0) out.add(new ArrayList<>(p)); return; } for(int x=start;x<=9&&x<=sum;x++){ p.add(x); dfs(x+1,k-1,sum-x,p,out); p.remove(p.size()-1); } }
    public static List<List<Integer>> solve(int k,int target){ if(k<0) throw new IllegalArgumentException(); List<List<Integer>> out=new ArrayList<>(); dfs(1,k,target,new ArrayList<>(),out); return out; }''','System.out.println(solve(3,9));','[[1, 2, 6], [1, 3, 5], [2, 3, 4]]',
    'Select exactly k distinct digits from 1..9 whose sum is target.', 'Choose increasing digits so each combination has one representation. State carries the next minimum digit, remaining count and remaining sum.', 'O(2^9*9) upper-bound enumeration time; O(9) working stack plus output.', '1+2+6, 1+3+5 and 2+3+4 are the three valid triples for nine.', 'k=0,target=0 yields an empty combination. Digits cannot repeat.')
add('Letter Combinations of a Phone Number', '''    private static final String[] MAP={"","","abc","def","ghi","jkl","mno","pqrs","tuv","wxyz"};
    private static void dfs(String digits,int i,StringBuilder p,List<String> out){ if(i==digits.length()){ out.add(p.toString()); return; } char digit=digits.charAt(i); if(digit<'2'||digit>'9') throw new IllegalArgumentException(); for(char c:MAP[digit-'0'].toCharArray()){ p.append(c); dfs(digits,i+1,p,out); p.deleteCharAt(p.length()-1); } }
    public static List<String> solve(String digits){ List<String> out=new ArrayList<>(); if(!digits.isEmpty()) dfs(digits,0,new StringBuilder(),out); return out; }''','System.out.println(solve("23"));','[ad, ae, af, bd, be, bf, cd, ce, cf]',
    'Return all letter strings represented by digits 2..9; empty input returns empty.', 'At each digit branch over its letters; copy the path after processing all digits. The product of independent per-digit choices gives every combination.', 'O(n*4^n) worst time/output; O(n) stack/path.', 'Choose a/b/c for 2, then d/e/f for 3.', 'Digits 0/1 have no letters and are rejected rather than silently skipping positions.')
add('Palindrome partitioning', '''    private static boolean palindrome(String s,int l,int r){ while(l<r) if(s.charAt(l++)!=s.charAt(r--)) return false; return true; }
    private static void dfs(String s,int start,List<String> p,List<List<String>> out){ if(start==s.length()){ out.add(new ArrayList<>(p)); return; } for(int end=start;end<s.length();end++) if(palindrome(s,start,end)){ p.add(s.substring(start,end+1)); dfs(s,end+1,p,out); p.remove(p.size()-1); } }
    public static List<List<String>> solve(String s){ List<List<String>> out=new ArrayList<>(); dfs(s,0,new ArrayList<>(),out); return out; }''','System.out.println(solve("aab"));','[[a, a, b], [aa, b]]',
    'Partition the whole string into contiguous palindromic parts; return every partition.', 'For each start, try every palindromic prefix and recursively partition the suffix. Each partition has a unique sequence of end positions.', 'O(n²*2^n) safe worst time bound for direct checks/copies; O(n) recursion depth plus output.', 'a -> a -> b gives [a,a,b]; aa -> b gives [aa,b].', 'Empty string has one empty partition. Substring creates new strings in Java 8.', 'Precompute a palindrome table in O(n²) to make each prefix check O(1); output remains exponential.')
add('Word Search', '''    private static boolean dfs(char[][] a,String word,int i,int r,int c,boolean[][] used){ if(i==word.length()) return true; if(r<0||r==a.length||c<0||c==a[0].length||used[r][c]||a[r][c]!=word.charAt(i)) return false; used[r][c]=true; boolean found=dfs(a,word,i+1,r+1,c,used)||dfs(a,word,i+1,r-1,c,used)||dfs(a,word,i+1,r,c+1,used)||dfs(a,word,i+1,r,c-1,used); used[r][c]=false; return found; }
    public static boolean solve(char[][] a,String word){ if(word.isEmpty()) return true; if(a.length==0||a[0].length==0) return false; boolean[][] used=new boolean[a.length][a[0].length]; for(int r=0;r<a.length;r++) for(int c=0;c<a[0].length;c++) if(dfs(a,word,0,r,c,used)) return true; return false; }''','System.out.println(solve(new char[][]{{\'A\',\'B\',\'C\',\'E\'},{\'S\',\'F\',\'C\',\'S\'},{\'A\',\'D\',\'E\',\'E\'}},"ABCCED"));','true',
    'Find a word via orthogonal steps in a rectangular character board without reusing a cell.', 'Try each start and recursively match one character per step. Mark a cell only for the current path, restoring it before returning so other paths may use it.', 'O(rows*cols*4^wordLength) safe upper bound; O(rows*cols+wordLength) auxiliary space.', 'ABCCED follows A(0,0),B(0,1),C(0,2),C(1,2),E(2,2),D(2,1).', 'A global permanently visited set is wrong: reuse is forbidden within a path, not across alternative searches.')
add('N Queen', '''    private static void dfs(int r,char[][] board,boolean[] col,boolean[] down,boolean[] up,List<List<String>> out){ int n=board.length; if(r==n){ List<String> rows=new ArrayList<>(); for(char[] row:board) rows.add(new String(row)); out.add(rows); return; } for(int c=0;c<n;c++) if(!col[c]&&!down[r-c+n-1]&&!up[r+c]){ col[c]=down[r-c+n-1]=up[r+c]=true; board[r][c]='Q'; dfs(r+1,board,col,down,up,out); board[r][c]='.'; col[c]=down[r-c+n-1]=up[r+c]=false; } }
    public static List<List<String>> solve(int n){ if(n<0) throw new IllegalArgumentException(); char[][] b=new char[n][n]; for(char[] row:b) Arrays.fill(row,'.'); List<List<String>> out=new ArrayList<>(); dfs(0,b,new boolean[n],new boolean[Math.max(0,2*n-1)],new boolean[Math.max(0,2*n-1)],out); return out; }''','System.out.println(solve(4).size());','2',
    'Return all n-by-n boards with n nonattacking queens, one in each row.', 'Place one queen per row. Boolean column and two diagonal arrays give O(1) conflict tests. Mark -> recurse -> unmark explores every valid placement.', 'O(n*n!) search upper bound plus O(n²) copying per result; O(n²) board and O(n) stack/flags.', 'For n=4, columns [1,3,0,2] and [2,0,3,1] are the two valid boards.', 'Diagonal indices are r-c+n-1 and r+c. n=0 gives one empty board.')
add('Rat in a Maze', '''    private static final int[] DR={1,0,0,-1},DC={0,-1,1,0}; private static final char[] DIR={'D','L','R','U'};
    private static void dfs(int[][] a,int r,int c,boolean[][] seen,StringBuilder p,List<String> out){ int n=a.length; if(r==n-1&&c==n-1){ out.add(p.toString()); return; } seen[r][c]=true; for(int d=0;d<4;d++){ int x=r+DR[d],y=c+DC[d]; if(x>=0&&y>=0&&x<n&&y<n&&a[x][y]==1&&!seen[x][y]){ p.append(DIR[d]); dfs(a,x,y,seen,p,out); p.deleteCharAt(p.length()-1); } } seen[r][c]=false; }
    public static List<String> solve(int[][] a){ List<String> out=new ArrayList<>(); int n=a.length; if(n==0) return out; for(int[] row:a) if(row.length!=n) throw new IllegalArgumentException(); if(a[0][0]==1&&a[n-1][n-1]==1) dfs(a,0,0,new boolean[n][n],new StringBuilder(),out); return out; }''','System.out.println(solve(new int[][]{{1,0},{1,1}}));','[DR]',
    'Return all simple open-cell paths in a square binary maze, top-left to bottom-right; directions D,L,R,U.', 'DFS marks only the current path. Explore directions in lexical order and restore visits so distinct paths remain possible.', 'Exponential path enumeration, O(4^(n²)) loose upper bound; O(n²) working space plus output.', 'For [[1,0],[1,1]], only down then right reaches the destination.', 'A blocked endpoint yields empty. A 1x1 open maze has one empty path, whose list prints ambiguously as [].')
add('M Coloring Problem', '''    private static boolean dfs(boolean[][] graph,int v,int[] color,int m){ if(v==graph.length) return true; for(int c=1;c<=m;c++){ boolean valid=true; for(int u=0;u<graph.length;u++) if((graph[v][u]||graph[u][v])&&(u==v||color[u]==c)){ valid=false; break; } if(valid){ color[v]=c; if(dfs(graph,v+1,color,m)) return true; color[v]=0; } } return false; }
    public static boolean solve(boolean[][] graph,int m){ if(m<0) throw new IllegalArgumentException(); return dfs(graph,0,new int[graph.length],m); }''','System.out.println(solve(new boolean[][]{{false,true,true},{true,false,true},{true,true,false}},3));','true',
    'Decide whether an undirected adjacency-matrix graph can be properly colored with at most m colors.', 'Choose a color for the next vertex only if no neighbor already has it. Recursively complete later vertices; restore failed choices. Every possible valid assignment is explored.', 'O(V*m^V) loose time upper bound; O(V) colors/stack excluding input.', 'A triangle needs three different colors; two cannot suffice.', 'A self-loop makes proper coloring impossible. Empty graph is colorable with zero colors.')
add('Sudoku Solver', '''    private static boolean valid(char[][] a,int r,int c,char x){ for(int i=0;i<9;i++) if(a[r][i]==x||a[i][c]==x||a[3*(r/3)+i/3][3*(c/3)+i%3]==x) return false; return true; }
    private static boolean dfs(char[][] a){ for(int r=0;r<9;r++) for(int c=0;c<9;c++) if(a[r][c]=='.'){ for(char x='1';x<='9';x++) if(valid(a,r,c,x)){ a[r][c]=x; if(dfs(a)) return true; a[r][c]='.'; } return false; } return true; }
    public static boolean solve(char[][] a){ if(a.length!=9) throw new IllegalArgumentException(); for(char[] row:a) if(row.length!=9) throw new IllegalArgumentException(); for(int r=0;r<9;r++) for(int c=0;c<9;c++) if(a[r][c]!='.'){ char x=a[r][c]; a[r][c]='.'; boolean ok=x>='1'&&x<='9'&&valid(a,r,c,x); a[r][c]=x; if(!ok) return false; } return dfs(a); }''','char[][] a={"53..7....".toCharArray(),"6..195...".toCharArray(),".98....6.".toCharArray(),"8...6...3".toCharArray(),"4..8.3..1".toCharArray(),"7...2...6".toCharArray(),".6....28.".toCharArray(),"...419..5".toCharArray(),"....8..79".toCharArray()}; System.out.println(solve(a)); System.out.println(new String(a[0]));','true\n534678912',
    'Solve a 9x9 Sudoku in place, with . for blanks. Return false if invalid or unsolvable, restoring attempted blank assignments.', 'Validate initial clues, then fill the first blank with each row/column/box-compatible digit. A failed continuation restores the blank. An all-filled valid board is the base success.', 'O(9^E) loose upper bound for E blanks with constant-size checks; O(E) stack.', 'First-row blanks are constrained by column and 3x3 box; the completed first row is 534678912.', 'Initial duplicates must be detected, otherwise an already-full invalid board would wrongly return true.')
add('Expression Add Operators', '''    private static void dfs(String s,int at,BigInteger value,BigInteger last,String expression,BigInteger target,List<String> out){ if(at==s.length()){ if(value.equals(target)) out.add(expression); return; } for(int end=at+1;end<=s.length();end++){ if(end>at+1&&s.charAt(at)=='0') break; String token=s.substring(at,end); BigInteger x=new BigInteger(token); if(at==0) dfs(s,end,x,x,token,target,out); else { dfs(s,end,value.add(x),x,expression+"+"+token,target,out); dfs(s,end,value.subtract(x),x.negate(),expression+"-"+token,target,out); BigInteger product=last.multiply(x); dfs(s,end,value.subtract(last).add(product),product,expression+"*"+token,target,out); } } }
    public static List<String> solve(String digits,long target){ for(char c:digits.toCharArray()) if(c<'0'||c>'9') throw new IllegalArgumentException(); List<String> out=new ArrayList<>(); if(!digits.isEmpty()) dfs(digits,0,BigInteger.ZERO,BigInteger.ZERO,"",BigInteger.valueOf(target),out); return out; }''','System.out.println(solve("123",6));','[1+2+3, 1*2*3]',
    'Insert +,-,* between digit groups to reach target; preserve digit order, use no parentheses and forbid multi-digit leading-zero operands.', 'Track total and the last signed multiplicative term. Multiplication replaces last with last*x in total, enforcing precedence without reparsing. Try all token endpoints and all operators.', 'Exponential O(n*4^n) loose search/string-cost bound, with additional BigInteger bit costs; O(n) depth plus expression storage/output.', '1+2 then *3 would replace +2 with +6, giving 7; 1*2*3 correctly evaluates 6.', 'BigInteger prevents expression overflow. A token 0 is valid, but 00 is not.')
